  if(/umidade absoluta|agua no ar|vapor de agua/.test(text))return m&&m.water!==null?'Há aproximadamente '+number(m.water)+' gramas de vapor em cada metro cúbico de ar, pela estimativa do painel.'+scope:'Preciso de uma leitura válida para estimar a quantidade de vapor no ar.';
