  if(/compar|mais quente.*ontem/.test(text)){const data=compare(comparisonData?.items||readings,/ontem/.test(text)?'days':/manha|tarde/.test(text)?'shifts':mode);if(comparisonError||compareBusy||!data.a||!data.b)return 'Ainda não tenho medições suficientes confirmadas para comparar esses períodos. No Início, use O ambiente mudou? e toque em Atualizar.';return `${data.aLabel}: ${number(data.a.temp)} °C e ${number(data.a.hum)}%. ${data.bLabel}: ${number(data.b.temp)} °C e ${number(data.b.hum)}%. ${data.scope} ${data.stale?'As leituras são antigas. ':''}${comparisonData?.partial?'A consulta pode estar incompleta. ':''}${data.detail||''}`;}
