 el('comparisonRefresh').addEventListener('click',()=>loadComparison(true));el('loadRecords').addEventListener('click',loadRecords);
 el('learningSearch').addEventListener('input',()=>{const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=normalize(el('learningSearch').value.trim());let count=0;document.querySelectorAll('[data-learning]').forEach(card=>{card.hidden=!normalize(card.textContent).includes(query);if(!card.hidden)count++;});el('learningEmpty').hidden=count>0;});

