 const layer=document.createElement('div');layer.className='hero-scenes';layer.setAttribute('aria-hidden','true');const images=scenes.map(([file,label,position],i)=>{const image=document.createElement('img');image.alt='';image.decoding='async';image.style.objectPosition=position;if(i===0){image.src='assets/escola-'+file+'.jpeg';image.className='active';image.fetchPriority='high';}layer.append(image);return image;});hero.prepend(layer);
 const controls=document.createElement('div');controls.className='hero-gallery-controls';controls.setAttribute('role','group');controls.setAttribute('aria-label','Imagens da escola');controls.innerHTML='<button type="button" id="heroPause"></button>';hero.append(controls);hero.querySelector('.illustration-label').textContent='Ilustrações do ambiente escolar';
 const motion=matchMedia('(prefers-reduced-motion: reduce)'),pause=document.getElementById('heroPause');let current=0,requested=0,request=0,interval,paused=motion.matches||!!navigator.connection?.saveData,hover=false,focused=false,visible=true;const failed=new Set();
 function sync(){clearTimeout(interval);pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Retomar troca automática':'Pausar troca automática');pause.setAttribute('aria-pressed',String(paused));if(!paused&&!hover&&!focused&&visible&&!document.hidden&&(!location.hash||location.hash==='#dashboard'))interval=setTimeout(()=>change(next(1)),7000);}
 function next(direction){let i=requested;for(let n=0;n<scenes.length;n++){i=(i+direction+scenes.length)%scenes.length;if(!failed.has(i))return i;}return current;}
 async function change(index){requested=index;const token=++request;clearTimeout(interval);const image=images[index];try{if(!image.getAttribute('src'))image.src='assets/escola-'+scenes[index][0]+'.jpeg';await image.decode();if(token!==request)return;images.forEach((img,i)=>img.classList.toggle('active',i===index));current=index;hero.dataset.scene=String(index);failed.delete(index);}catch{if(token!==request)return;failed.add(index);}finally{if(token===request)sync();}}
